extern "C" LEAN_EXPORT obj_res lean_io_prim_handle_get_line(b_obj_arg h, obj_arg /* w */) {
    FILE * fp = io_get_handle(h);

    std::string result;
    int c; // Note: int, not char, required to handle EOF
    while ((c = std::fgetc(fp)) != EOF) {
        result.push_back(c);
        if (c == '\n') {
